function hasPath(graph, from, to) {
  const visited = new Set();
  const stack = [from];
  while (stack.length) {
    const node = stack.pop();
    if (node === to) return true;
    if (visited.has(node)) continue;
    visited.add(node);
    stack.push(...graph[node]);
  }
  return false;
}

